volume.script:
var a = BINANCE:auctionusdc;
var b = BINANCE:auctionusdt;
var c = BINANCE_FUTURES:auctionusdt;
var d = BYBIT:AUCTIONUSDT;
var e = COINBASE:AUCTION-USD;
var f = COINBASE:AUCTION-USDC;
var g = KRAKEN:AUCTION/USD;
var h = KRAKEN:PF_AUCTIONUSD;
var i = OKEX:AUCTION-USD;
var j = OKEX:AUCTION-USDT;
var k = OKEX:AUCTION-USDT-SWAP;
var l = UPBIT:KRW-AUCTION;

if (upColor === 0) {
  if (options.showDelta) {
    upColor = options.upBgColor
    downColor = options.downBgColor
  } else {
    upColor = options.upColor
    downColor = options.downColor
  }
}

var totalVbuy = a.vbuy+b.vbuy+c.vbuy+d.vbuy+e.vbuy+f.vbuy+g.vbuy+h.vbuy+i.vbuy+j.vbuy+k.vbuy+l.vbuy;
var totalVsell = a.vsell+b.vsell+c.vsell+d.vsell+e.vsell+f.vsell+g.vsell+h.vsell+i.vsell+j.vsell+k.vsell+l.vsell;

if (options.showDelta) {
  plothistogram({ time: time, value: Math.abs(totalVbuy-totalVsell), color: totalVbuy - totalVsell > 0 ? options.upColor : options.downColor})
}

plothistogram({ time: time, value: totalVbuy + totalVsell, color: totalVbuy > totalVsell ? upColor : downColor })

cvd-perp.script:
var a = BINANCE_FUTURES:auctionusdt;
