line(cum(a.vbuy-a.vsell), title="BINANCE_FUTURES", color="rgb(240, 185, 11)");

line(cum(b.vbuy-b.vsell), title="BYBIT", color="rgb(255, 184, 0)");

line(cum(c.vbuy-c.vsell), title="KRAKEN", color="rgb(92, 46, 145)");

line(cum(d.vbuy-d.vsell), title="OKEX", color="rgb(13, 110, 253)");

line(cum(a.vbuy-a.vsell+b.vbuy-b.vsell+c.vbuy-c.vsell+d.vbuy-d.vsell), title="total", color="rgb(255,25,183)");

cvd-spot.script:
var a = BINANCE:auctionusdt;
var b = BINANCE:auctionusdc;
var c = COINBASE:AUCTION-USD;
var d = COINBASE:AUCTION-USDC;
var e = KRAKEN:AUCTION/USD;
var f = OKEX:AUCTION-USD;
