  } else {
    upColor = options.upColor
    downColor = options.downColor
  }
}

var totalVbuy = a.vbuy+b.vbuy+c.vbuy+d.vbuy+e.vbuy+f.vbuy+g.vbuy+h.vbuy+i.vbuy+j.vbuy+k.vbuy+l.vbuy+m.vbuy+n.vbuy+o.vbuy;
