volume.script:
var a = BINANCE:iousdc;
var b = BINANCE:iousdt;
var c = BINANCE_FUTURES:iousdt;
var d = BYBIT:IOUSDT;
var e = BYBIT:IOUSDT-SPOT;
var f = COINBASE:IO-USD;
var g = COINBASE:IO-USDC;
var h = HYPERLIQUID:IO-USD;
var i = KRAKEN:PF_IOUSD;

if (upColor === 0) {
  if (options.showDelta) {
    upColor = options.upBgColor
    downColor = options.downBgColor
  } else {
    upColor = options.upColor
    downColor = options.downColor
  }
}

var totalVbuy = a.vbuy+b.vbuy+c.vbuy+d.vbuy+e.vbuy+f.vbuy+g.vbuy+h.vbuy+i.vbuy;
var totalVsell = a.vsell+b.vsell+c.vsell+d.vsell+e.vsell+f.vsell+g.vsell+h.vsell+i.vsell;

if (options.showDelta) {
  plothistogram({ time: time, value: Math.abs(totalVbuy-totalVsell), color: totalVbuy - totalVsell > 0 ? options.upColor : options.downColor})
}

plothistogram({ time: time, value: totalVbuy + totalVsell, color: totalVbuy > totalVsell ? upColor : downColor })

cvd-perp.script:
var a = BINANCE_FUTURES:iousdt;
var b = BYBIT:IOUSDT;
var c = KRAKEN:PF_IOUSD;
var d = HYPERLIQUID:IO-USD;

line(cum(a.vbuy-a.vsell), title="BINANCE_FUTURES", color="rgb(240, 185, 11)");

line(cum(b.vbuy-b.vsell), title="BYBIT", color="rgb(255, 184, 0)");

line(cum(d.vbuy-d.vsell), title="HYPERLIQUID", color="rgb(0, 255, 194)");

line(cum(c.vbuy-c.vsell), title="KRAKEN", color="rgb(92, 46, 145)");

line(cum(a.vbuy-a.vsell+b.vbuy-b.vsell+d.vbuy-d.vsell+c.vbuy-c.vsell), title="total", color="rgb(255,25,183)");

cvd-spot.script:
var a = BINANCE:iousdt;
var b = BINANCE:iousdc;
var c = BYBIT:IOUSDT-SPOT;
var d = COINBASE:IO-USD;
var e = COINBASE:IO-USDC;

line(cum(a.vbuy-a.vsell+b.vbuy-b.vsell), title="BINANCE", color="rgb(240, 185, 11)");

line(cum(c.vbuy-c.vsell), title="BYBIT", color="rgb(255, 184, 0)");

line(cum(d.vbuy-d.vsell+e.vbuy-e.vsell), title="COINBASE", color="rgb(0, 82, 255)");

line(cum(a.vbuy-a.vsell+b.vbuy-b.vsell+c.vbuy-c.vsell+d.vbuy-d.vsell+e.vbuy-e.vsell), title="total", color="rgb(255,25,183)");

vwap.script:
var src = ($price.high + $price.low + $price.close)/3
var vol=vbuy+vsell
var sumVol = cum(vol)
var sumSrcVol = cum(src * vol)
var sumSrcSrcVol = cum(vol*Math.pow(src, 2))
var VWAP = sumSrcVol / sumVol 
var variance = sumSrcSrcVol / sumVol - Math.pow(VWAP, 2)
var stDev = Math.sqrt(variance < 0 ? 0 : variance)

line(VWAP)
cloudarea(VWAP - stDev * options.stdevMultiplier, VWAP + stDev * options.stdevMultiplier)

var unixDays = bar.timestamp / 60 / 60 / 24 + 3
if (unixDays % (options.sessionLengthInDays) === 0) {
  fns[0].state = {}
  fns[1].state = {}
  fns[2].state = {}
}

