volume.script:
var a = BINANCE_FUTURES:monusdt;
var b = BYBIT:MONUSDT;
var c = BYBIT:MONUSDT-SPOT;
var d = COINBASE:MON-USD;
var e = COINBASE:MON-USDC;
var f = HYPERLIQUID:MON-USD;
var g = HYPERLIQUID_SPOT:MON/USDC;
var h = KRAKEN:MON/USD;
var i = OKEX:MON-USDT-SWAP;
var j = UPBIT:KRW-MON;

if (upColor === 0) {
  if (options.showDelta) {
    upColor = options.upBgColor
    downColor = options.downBgColor
  } else {
    upColor = options.upColor
    downColor = options.downColor
  }
}

var totalVbuy = a.vbuy+b.vbuy+c.vbuy+d.vbuy+e.vbuy+f.vbuy+g.vbuy+h.vbuy+i.vbuy+j.vbuy;
var totalVsell = a.vsell+b.vsell+c.vsell+d.vsell+e.vsell+f.vsell+g.vsell+h.vsell+i.vsell+j.vsell;

if (options.showDelta) {
  plothistogram({ time: time, value: Math.abs(totalVbuy-totalVsell), color: totalVbuy - totalVsell > 0 ? options.upColor : options.downColor})
}

plothistogram({ time: time, value: totalVbuy + totalVsell, color: totalVbuy > totalVsell ? upColor : downColor })

cvd-perp.script:
var a = BINANCE_FUTURES:monusdt;
var b = BYBIT:MONUSDT;
var c = OKEX:MON-USDT-SWAP;
var d = HYPERLIQUID:MON-USD;

line(cum(a.vbuy-a.vsell), title="BINANCE_FUTURES", color="rgb(240, 185, 11)");

line(cum(b.vbuy-b.vsell), title="BYBIT", color="rgb(255, 184, 0)");

line(cum(d.vbuy-d.vsell), title="HYPERLIQUID", color="rgb(0, 255, 194)");

line(cum(c.vbuy-c.vsell), title="OKEX", color="rgb(13, 110, 253)");

line(cum(a.vbuy-a.vsell+b.vbuy-b.vsell+d.vbuy-d.vsell+c.vbuy-c.vsell), title="total", color="rgb(255,25,183)");

cvd-spot.script:
var a = BYBIT:MONUSDT-SPOT;
var b = COINBASE:MON-USD;
var c = COINBASE:MON-USDC;
var d = KRAKEN:MON/USD;
var e = UPBIT:KRW-MON;
var f = HYPERLIQUID_SPOT:MON/USDC;

line(cum(a.vbuy-a.vsell), title="BYBIT", color="rgb(255, 184, 0)");

line(cum(b.vbuy-b.vsell+c.vbuy-c.vsell), title="COINBASE", color="rgb(0, 82, 255)");

line(cum(f.vbuy-f.vsell), title="HYPERLIQUID_SPOT", color="rgb(240,169,5)");

line(cum(d.vbuy-d.vsell), title="KRAKEN", color="rgb(92, 46, 145)");

line(cum(e.vbuy-e.vsell), title="UPBIT", color="rgb(52, 144, 220)");

line(cum(a.vbuy-a.vsell+b.vbuy-b.vsell+c.vbuy-c.vsell+f.vbuy-f.vsell+d.vbuy-d.vsell+e.vbuy-e.vsell), title="total", color="rgb(255,25,183)");

vwap.script:
var src = ($price.high + $price.low + $price.close)/3
var vol=vbuy+vsell
var sumVol = cum(vol)
var sumSrcVol = cum(src * vol)
var sumSrcSrcVol = cum(vol*Math.pow(src, 2))
var VWAP = sumSrcVol / sumVol 
var variance = sumSrcSrcVol / sumVol - Math.pow(VWAP, 2)
var stDev = Math.sqrt(variance < 0 ? 0 : variance)

line(VWAP)
cloudarea(VWAP - stDev * options.stdevMultiplier, VWAP + stDev * options.stdevMultiplier)

var unixDays = bar.timestamp / 60 / 60 / 24 + 3
if (unixDays % (options.sessionLengthInDays) === 0) {
  fns[0].state = {}
  fns[1].state = {}
  fns[2].state = {}
}

