volume.script:
var a = BINANCE:moveusdc;
var b = BINANCE:moveusdt;
var c = BINANCE_FUTURES:moveusdt;
var d = BYBIT:MOVEUSDC-SPOT;
var e = BYBIT:MOVEUSDT;
var f = BYBIT:MOVEUSDT-SPOT;
var g = HYPERLIQUID:MOVE-USD;
var h = KRAKEN:MOVE/USD;
var i = KRAKEN:PF_MOVEUSD;
var j = OKEX:MOVE-USD;
var k = OKEX:MOVE-USDT;
var l = OKEX:MOVE-USDT-SWAP;
var m = UPBIT:KRW-MOVE;

if (upColor === 0) {
  if (options.showDelta) {
    upColor = options.upBgColor
    downColor = options.downBgColor
  } else {
    upColor = options.upColor
    downColor = options.downColor
  }
}

var totalVbuy = a.vbuy+b.vbuy+c.vbuy+d.vbuy+e.vbuy+f.vbuy+g.vbuy+h.vbuy+i.vbuy+j.vbuy+k.vbuy+l.vbuy+m.vbuy;
var totalVsell = a.vsell+b.vsell+c.vsell+d.vsell+e.vsell+f.vsell+g.vsell+h.vsell+i.vsell+j.vsell+k.vsell+l.vsell+m.vsell;

if (options.showDelta) {
  plothistogram({ time: time, value: Math.abs(totalVbuy-totalVsell), color: totalVbuy - totalVsell > 0 ? options.upColor : options.downColor})
}

plothistogram({ time: time, value: totalVbuy + totalVsell, color: totalVbuy > totalVsell ? upColor : downColor })

cvd-perp.script:
var a = BINANCE_FUTURES:moveusdt;
var b = BYBIT:MOVEUSDT;
var c = KRAKEN:PF_MOVEUSD;
var d = OKEX:MOVE-USDT-SWAP;
var e = HYPERLIQUID:MOVE-USD;

line(cum(a.vbuy-a.vsell), title="BINANCE_FUTURES", color="rgb(240, 185, 11)");

line(cum(b.vbuy-b.vsell), title="BYBIT", color="rgb(255, 184, 0)");

line(cum(e.vbuy-e.vsell), title="HYPERLIQUID", color="rgb(0, 255, 194)");

line(cum(c.vbuy-c.vsell), title="KRAKEN", color="rgb(92, 46, 145)");

line(cum(d.vbuy-d.vsell), title="OKEX", color="rgb(13, 110, 253)");

line(cum(a.vbuy-a.vsell+b.vbuy-b.vsell+e.vbuy-e.vsell+c.vbuy-c.vsell+d.vbuy-d.vsell), title="total", color="rgb(255,25,183)");

cvd-spot.script:
var a = BINANCE:moveusdt;
var b = BINANCE:moveusdc;
var c = BYBIT:MOVEUSDT-SPOT;
var d = BYBIT:MOVEUSDC-SPOT;
var e = KRAKEN:MOVE/USD;
var f = OKEX:MOVE-USD;
var g = OKEX:MOVE-USDT;
var h = UPBIT:KRW-MOVE;

line(cum(a.vbuy-a.vsell+b.vbuy-b.vsell), title="BINANCE", color="rgb(240, 185, 11)");

line(cum(c.vbuy-c.vsell+d.vbuy-d.vsell), title="BYBIT", color="rgb(255, 184, 0)");

line(cum(e.vbuy-e.vsell), title="KRAKEN", color="rgb(92, 46, 145)");

line(cum(f.vbuy-f.vsell+g.vbuy-g.vsell), title="OKEX", color="rgb(13, 110, 253)");

line(cum(h.vbuy-h.vsell), title="UPBIT", color="rgb(52, 144, 220)");

line(cum(a.vbuy-a.vsell+b.vbuy-b.vsell+c.vbuy-c.vsell+d.vbuy-d.vsell+e.vbuy-e.vsell+f.vbuy-f.vsell+g.vbuy-g.vsell+h.vbuy-h.vsell), title="total", color="rgb(255,25,183)");

vwap.script:
var src = ($price.high + $price.low + $price.close)/3
var vol=vbuy+vsell
var sumVol = cum(vol)
var sumSrcVol = cum(src * vol)
var sumSrcSrcVol = cum(vol*Math.pow(src, 2))
var VWAP = sumSrcVol / sumVol 
var variance = sumSrcSrcVol / sumVol - Math.pow(VWAP, 2)
var stDev = Math.sqrt(variance < 0 ? 0 : variance)

line(VWAP)
cloudarea(VWAP - stDev * options.stdevMultiplier, VWAP + stDev * options.stdevMultiplier)

var unixDays = bar.timestamp / 60 / 60 / 24 + 3
if (unixDays % (options.sessionLengthInDays) === 0) {
  fns[0].state = {}
  fns[1].state = {}
  fns[2].state = {}
}

