volume.script:
var a = BINANCE:nilusdc;
var b = BINANCE:nilusdt;
var c = BINANCE_FUTURES:nilusdt;
var d = BYBIT:NILUSDT;
var e = HYPERLIQUID:NIL-USD;
var f = KRAKEN:NIL/USD;

if (upColor === 0) {
  if (options.showDelta) {
    upColor = options.upBgColor
    downColor = options.downBgColor
  } else {
    upColor = options.upColor
    downColor = options.downColor
  }
}

var totalVbuy = a.vbuy+b.vbuy+c.vbuy+d.vbuy+e.vbuy+f.vbuy;
var totalVsell = a.vsell+b.vsell+c.vsell+d.vsell+e.vsell+f.vsell;

if (options.showDelta) {
  plothistogram({ time: time, value: Math.abs(totalVbuy-totalVsell), color: totalVbuy - totalVsell > 0 ? options.upColor : options.downColor})
}

plothistogram({ time: time, value: totalVbuy + totalVsell, color: totalVbuy > totalVsell ? upColor : downColor })

cvd-perp.script:
var a = BINANCE_FUTURES:nilusdt;
var b = BYBIT:NILUSDT;
var c = HYPERLIQUID:NIL-USD;

line(cum(a.vbuy-a.vsell), title="BINANCE_FUTURES", color="rgb(240, 185, 11)");

line(cum(b.vbuy-b.vsell), title="BYBIT", color="rgb(255, 184, 0)");

line(cum(c.vbuy-c.vsell), title="HYPERLIQUID", color="rgb(0, 255, 194)");

line(cum(a.vbuy-a.vsell+b.vbuy-b.vsell+c.vbuy-c.vsell), title="total", color="rgb(255,25,183)");

cvd-spot.script:
var a = BINANCE:nilusdt;
var b = BINANCE:nilusdc;
var c = KRAKEN:NIL/USD;

line(cum(a.vbuy-a.vsell+b.vbuy-b.vsell), title="BINANCE", color="rgb(240, 185, 11)");

line(cum(c.vbuy-c.vsell), title="KRAKEN", color="rgb(92, 46, 145)");

line(cum(a.vbuy-a.vsell+b.vbuy-b.vsell+c.vbuy-c.vsell), title="total", color="rgb(255,25,183)");

vwap.script:
var src = ($price.high + $price.low + $price.close)/3
var vol=vbuy+vsell
var sumVol = cum(vol)
var sumSrcVol = cum(src * vol)
var sumSrcSrcVol = cum(vol*Math.pow(src, 2))
var VWAP = sumSrcVol / sumVol 
var variance = sumSrcSrcVol / sumVol - Math.pow(VWAP, 2)
var stDev = Math.sqrt(variance < 0 ? 0 : variance)

line(VWAP)
cloudarea(VWAP - stDev * options.stdevMultiplier, VWAP + stDev * options.stdevMultiplier)

var unixDays = bar.timestamp / 60 / 60 / 24 + 3
if (unixDays % (options.sessionLengthInDays) === 0) {
  fns[0].state = {}
  fns[1].state = {}
  fns[2].state = {}
}

