volume.script:
var a = BINANCE:skyusdc;
var b = BINANCE:skyusdt;
var c = BINANCE_FUTURES:skyusdt;
var d = BITFINEX:SKYUSD;
var e = BITFINEX:SKYUST;
var f = BYBIT:SKYUSDT;
var g = BYBIT:SKYUSDT-SPOT;
var h = COINBASE:SKY-USD;
var i = COINBASE:SKY-USDC;
var j = HYPERLIQUID:SKY-USD;
var k = KRAKEN:SKY/USD;
var l = OKEX:SKY-USD;
var m = OKEX:SKY-USDT;
var n = OKEX:SKY-USDT-SWAP;

if (upColor === 0) {
  if (options.showDelta) {
    upColor = options.upBgColor
    downColor = options.downBgColor
  } else {
    upColor = options.upColor
    downColor = options.downColor
  }
}

var totalVbuy = a.vbuy+b.vbuy+c.vbuy+d.vbuy+e.vbuy+f.vbuy+g.vbuy+h.vbuy+i.vbuy+j.vbuy+k.vbuy+l.vbuy+m.vbuy+n.vbuy;
var totalVsell = a.vsell+b.vsell+c.vsell+d.vsell+e.vsell+f.vsell+g.vsell+h.vsell+i.vsell+j.vsell+k.vsell+l.vsell+m.vsell+n.vsell;

if (options.showDelta) {
  plothistogram({ time: time, value: Math.abs(totalVbuy-totalVsell), color: totalVbuy - totalVsell > 0 ? options.upColor : options.downColor})
}

plothistogram({ time: time, value: totalVbuy + totalVsell, color: totalVbuy > totalVsell ? upColor : downColor })

cvd-perp.script:
var a = BINANCE_FUTURES:skyusdt;
var b = BYBIT:SKYUSDT;
var c = OKEX:SKY-USDT-SWAP;
var d = HYPERLIQUID:SKY-USD;

line(cum(a.vbuy-a.vsell), title="BINANCE_FUTURES", color="rgb(240, 185, 11)");

line(cum(b.vbuy-b.vsell), title="BYBIT", color="rgb(255, 184, 0)");

line(cum(d.vbuy-d.vsell), title="HYPERLIQUID", color="rgb(0, 255, 194)");

line(cum(c.vbuy-c.vsell), title="OKEX", color="rgb(13, 110, 253)");

line(cum(a.vbuy-a.vsell+b.vbuy-b.vsell+d.vbuy-d.vsell+c.vbuy-c.vsell), title="total", color="rgb(255,25,183)");

cvd-spot.script:
var a = BINANCE:skyusdc;
var b = BINANCE:skyusdt;
var c = BITFINEX:SKYUSD;
var d = BITFINEX:SKYUST;
var e = BYBIT:SKYUSDT-SPOT;
var f = COINBASE:SKY-USD;
var g = COINBASE:SKY-USDC;
var h = KRAKEN:SKY/USD;
var i = OKEX:SKY-USD;
var j = OKEX:SKY-USDT;

line(cum(a.vbuy-a.vsell+b.vbuy-b.vsell), title="BINANCE", color="rgb(240, 185, 11)");

line(cum(c.vbuy-c.vsell+d.vbuy-d.vsell), title="BITFINEX", color="rgb(17, 153, 142)");

line(cum(e.vbuy-e.vsell), title="BYBIT", color="rgb(255, 184, 0)");

line(cum(f.vbuy-f.vsell+g.vbuy-g.vsell), title="COINBASE", color="rgb(0, 82, 255)");

line(cum(h.vbuy-h.vsell), title="KRAKEN", color="rgb(92, 46, 145)");

line(cum(i.vbuy-i.vsell+j.vbuy-j.vsell), title="OKEX", color="rgb(13, 110, 253)");

line(cum(a.vbuy-a.vsell+b.vbuy-b.vsell+c.vbuy-c.vsell+d.vbuy-d.vsell+e.vbuy-e.vsell+f.vbuy-f.vsell+g.vbuy-g.vsell+h.vbuy-h.vsell+i.vbuy-i.vsell+j.vbuy-j.vsell), title="total", color="rgb(255,25,183)");

vwap.script:
var src = ($price.high + $price.low + $price.close)/3
var vol=vbuy+vsell
var sumVol = cum(vol)
var sumSrcVol = cum(src * vol)
var sumSrcSrcVol = cum(vol*Math.pow(src, 2))
var VWAP = sumSrcVol / sumVol 
var variance = sumSrcSrcVol / sumVol - Math.pow(VWAP, 2)
var stDev = Math.sqrt(variance < 0 ? 0 : variance)

line(VWAP)
cloudarea(VWAP - stDev * options.stdevMultiplier, VWAP + stDev * options.stdevMultiplier)

var unixDays = bar.timestamp / 60 / 60 / 24 + 3
if (unixDays % (options.sessionLengthInDays) === 0) {
  fns[0].state = {}
  fns[1].state = {}
  fns[2].state = {}
}

