volume.script:
var a = BINANCE:xplusdc;
var b = BINANCE:xplusdt;
var c = BINANCE_FUTURES:xplusdt;
var d = BITFINEX:XPLUSD;
var e = BITFINEX:XPLUST;
var f = BITSTAMP:xplusd;
var g = BYBIT:XPLUSDT-SPOT;
var h = HYPERLIQUID:XPL-USD;
var i = HYPERLIQUID_SPOT:UXPL/USDC;
var j = KRAKEN:PF_XPLUSD;
var k = KRAKEN:XPL/USD;
var l = OKEX:XPL-USD;
var m = OKEX:XPL-USDT;
var n = OKEX:XPL-USDT-SWAP;
var o = UPBIT:KRW-XPL;

if (upColor === 0) {
  if (options.showDelta) {
    upColor = options.upBgColor
    downColor = options.downBgColor
  } else {
    upColor = options.upColor
    downColor = options.downColor
  }
}

var totalVbuy = a.vbuy+b.vbuy+c.vbuy+d.vbuy+e.vbuy+f.vbuy+g.vbuy+h.vbuy+i.vbuy+j.vbuy+k.vbuy+l.vbuy+m.vbuy+n.vbuy+o.vbuy;
var totalVsell = a.vsell+b.vsell+c.vsell+d.vsell+e.vsell+f.vsell+g.vsell+h.vsell+i.vsell+j.vsell+k.vsell+l.vsell+m.vsell+n.vsell+o.vsell;

if (options.showDelta) {
  plothistogram({ time: time, value: Math.abs(totalVbuy-totalVsell), color: totalVbuy - totalVsell > 0 ? options.upColor : options.downColor})
}

plothistogram({ time: time, value: totalVbuy + totalVsell, color: totalVbuy > totalVsell ? upColor : downColor })

