var i = OKEX:ZRX-USDT;
var j = UPBIT:KRW-ZRX;

line(cum(a.vbuy-a.vsell), title="BINANCE", color="rgb(240, 185, 11)");

line(cum(b.vbuy-b.vsell), title="BITFINEX", color="rgb(17, 153, 142)");

line(cum(c.vbuy-c.vsell), title="BITSTAMP", color="rgb(14, 182, 156)");

line(cum(d.vbuy-d.vsell), title="BYBIT", color="rgb(255, 184, 0)");

line(cum(e.vbuy-e.vsell+f.vbuy-f.vsell), title="COINBASE", color="rgb(0, 82, 255)");

line(cum(g.vbuy-g.vsell), title="KRAKEN", color="rgb(92, 46, 145)");

line(cum(h.vbuy-h.vsell+i.vbuy-i.vsell), title="OKEX", color="rgb(13, 110, 253)");

